 async void ImportCourseImage(){if(ocrBusy)return;var file=new Microsoft.Win32.OpenFileDialog{Filter="课表图片|*.png;*.jpg;*.jpeg;*.bmp"};if(file.ShowDialog(Window)!=true)return;string image=null,result=Path.GetTempFileName();try{image=CropCourseImage(file.FileName);if(image==null)return;ocrBusy=true;C<TextBlock>("FooterMessage").Text="正在本机识别与分析课程单元格…";string script=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"OfflineOcr.ps1");if(!File.Exists(script))script=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"source","OfflineOcr.ps1");string finalImage=image;await System.Threading.Tasks.Task.Run(delegate{var info=new System.Diagnostics.ProcessStartInfo("powershell.exe","-NoProfile -ExecutionPolicy Bypass -File \""+script+"\" -ImagePath \""+finalImage+"\" -ResultPath \""+result+"\""){UseShellExecute=false,CreateNoWindow=true,RedirectStandardError=true};using(var p=System.Diagnostics.Process.Start(info)){string error=p.StandardError.ReadToEnd();p.WaitForExit();if(p.ExitCode!=0)throw new Exception(error);}});var rows=CourseRecognition.Parse(OcrLayout.Parse(File.ReadAllText(result)),image);if(rows.Count==0)throw new Exception("没有提取到课程单元格，请重新裁剪后识别。");ReviewOcr(rows,image);}catch(Exception ex){MessageBox.Show(Window,"离线识别未完成："+ex.Message);}finally{ocrBusy=false;File.Delete(result);if(image!=null)File.Delete(image);}}
 BitmapSource ReadBitmap(string file){var b=new BitmapImage();b.BeginInit();b.CacheOption=BitmapCacheOption.OnLoad;b.UriSource=new Uri(Path.GetFullPath(file));b.EndInit();b.Freeze();return b;}
 string CropCourseImage(string file){BitmapSource bitmap=ReadBitmap(file);var w=new Window{Owner=Window,Title="裁剪与校正课表",Width=900,Height=680,WindowStartupLocation=WindowStartupLocation.CenterOwner};var root=new DockPanel{Margin=new Thickness(20)};w.Content=root;var buttons=new StackPanel{Orientation=Orientation.Horizontal};DockPanel.SetDock(buttons,Dock.Bottom);root.Children.Add(buttons);var help=Text("拖动框选课表区域；未框选时识别整图。可先旋转校正。",13,"#71816B");DockPanel.SetDock(help,Dock.Top);root.Children.Add(help);var image=new Image{Source=bitmap,Stretch=Stretch.Uniform,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};var overlay=new Canvas{Background=Brushes.Transparent,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};var panel=new Grid();panel.Children.Add(image);panel.Children.Add(overlay);root.Children.Add(panel);overlay.SetBinding(FrameworkElement.WidthProperty,new System.Windows.Data.Binding("ActualWidth"){Source=image});overlay.SetBinding(FrameworkElement.HeightProperty,new System.Windows.Data.Binding("ActualHeight"){Source=image});var border=new System.Windows.Shapes.Rectangle{Stroke=B("#356A51"),StrokeThickness=2,Fill=new SolidColorBrush(Color.FromArgb(25,53,106,81))};overlay.Children.Add(border);Point start=new Point();Rect selection=Rect.Empty;overlay.MouseLeftButtonDown+=delegate(object sender,MouseButtonEventArgs e){start=e.GetPosition(overlay);overlay.CaptureMouse();};overlay.MouseMove+=delegate(object sender,MouseEventArgs e){if(!overlay.IsMouseCaptured)return;Point end=e.GetPosition(overlay);selection=new Rect(start,end);Canvas.SetLeft(border,selection.Left);Canvas.SetTop(border,selection.Top);border.Width=selection.Width;border.Height=selection.Height;};overlay.MouseLeftButtonUp+=delegate{overlay.ReleaseMouseCapture();};Action<double> rotate=delegate(double angle){bitmap=new TransformedBitmap(bitmap,new RotateTransform(angle));bitmap.Freeze();image.Source=bitmap;selection=Rect.Empty;border.Width=border.Height=0;};buttons.Children.Add(Btn("旋转90°",delegate{rotate(90);}));buttons.Children.Add(Btn("左转1°",delegate{rotate(-1);}));buttons.Children.Add(Btn("右转1°",delegate{rotate(1);}));string result=null;buttons.Children.Add(Btn("开始离线识别",delegate{try{BitmapSource cropped=bitmap;if(!selection.IsEmpty&&selection.Width>10&&selection.Height>10){double sx=bitmap.PixelWidth/Math.Max(1,overlay.ActualWidth),sy=bitmap.PixelHeight/Math.Max(1,overlay.ActualHeight);int x=Math.Max(0,(int)(selection.X*sx)),y=Math.Max(0,(int)(selection.Y*sy)),width=Math.Min(bitmap.PixelWidth-x,(int)(selection.Width*sx)),height=Math.Min(bitmap.PixelHeight-y,(int)(selection.Height*sy));cropped=new CroppedBitmap(bitmap,new Int32Rect(x,y,width,height));}result=Path.Combine(Path.GetTempPath(),"shiri-ocr-"+Guid.NewGuid().ToString("N")+".png");var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(cropped));using(var f=File.Create(result))encoder.Save(f);w.Close();}catch(Exception ex){MessageBox.Show(w,ex.Message);}}));w.ShowDialog();return result;}
 void ReviewOcr(List<OcrCandidate> candidates,string imagePath){
 var w=new Window{Owner=Window,Title="课表识别 · 核对后导入",Width=1080,Height=720,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=B("#F8F9F6"),Resources=Window.Resources};var root=new DockPanel{Margin=new Thickness(20)};w.Content=root;var top=new StackPanel{Orientation=Orientation.Horizontal};var preview=new Image{Source=ReadBitmap(imagePath),Height=150,MaxWidth=430,Stretch=Stretch.Uniform};top.Children.Add(preview);preview.MouseLeftButtonUp+=delegate{var zoom=new Window{Owner=w,Title="识别原图",Width=1000,Height=720,Content=new Image{Source=ReadBitmap(imagePath),Stretch=Stretch.Uniform},WindowStartupLocation=WindowStartupLocation.CenterOwner};zoom.ShowDialog();};var controls=new StackPanel{Margin=new Thickness(20,5,0,0)};controls.Children.Add(Text("原图无周次时，请批量选择应用周次",13,"#AD8850"));var weeks=new List<string>{"请选择"};weeks.AddRange(Enumerable.Range(1,state.Timetable.TotalWeeks).Select(n=>"第 "+n+" 周"));ComboBox from=new ComboBox{ItemsSource=weeks,SelectedIndex=0,Width=150,Margin=new Thickness(0,12,0,0)},to=new ComboBox{ItemsSource=weeks,SelectedIndex=0,Width=150,Margin=new Thickness(0,8,0,0)};controls.Children.Add(from);controls.Children.Add(to);top.Children.Add(controls);DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);var actions=new StackPanel{Orientation=Orientation.Horizontal,Margin=new Thickness(0,16,0,0)};DockPanel.SetDock(actions,Dock.Bottom);root.Children.Add(actions);
 var rows=candidates.Select(c=>new RecognitionRow(c)).ToList();var grid=new DataGrid{AutoGenerateColumns=false,ItemsSource=rows,CanUserAddRows=false,CanUserDeleteRows=false,RowHeight=44,Margin=new Thickness(0,18,0,0),HeadersVisibility=DataGridHeadersVisibility.Column};grid.Columns.Add(new DataGridCheckBoxColumn{Header="导入",Binding=new System.Windows.Data.Binding("Include"),Width=48});foreach(string name in new[]{"Title","Location","Start","End"})grid.Columns.Add(new DataGridTextColumn{Header=name=="Title"?"课程名称":name=="Location"?"地点":name=="Start"?"开始时间":"结束时间",Binding=new System.Windows.Data.Binding(name){UpdateSourceTrigger=System.Windows.Data.UpdateSourceTrigger.PropertyChanged},Width=name=="Title"||name=="Location"?170:90});foreach(string name in new[]{"Day","FirstWeek","LastWeek"})grid.Columns.Add(new DataGridComboBoxColumn{Header=name=="Day"?"星期":name=="FirstWeek"?"起始周":"结束周",ItemsSource=Enumerable.Range(1,name=="Day"?7:state.Timetable.TotalWeeks).ToList(),SelectedItemBinding=new System.Windows.Data.Binding(name){UpdateSourceTrigger=System.Windows.Data.UpdateSourceTrigger.PropertyChanged},Width=75});grid.LoadingRow+=delegate(object sender,DataGridRowEventArgs e){var row=e.Row.Item as RecognitionRow;if(row!=null&&(row.Day==0||row.FirstWeek==0||String.IsNullOrWhiteSpace(row.Title)))e.Row.Background=B("#FBF2DF");};root.Children.Add(grid);
 actions.Children.Add(Btn("交换选中行名称 / 地点",delegate{grid.CommitEdit();var row=grid.SelectedItem as RecognitionRow;if(row==null)return;string title=row.Title;row.Title=row.Location;row.Location=title;grid.Items.Refresh();}));bool committed=false;actions.Children.Add(Btn("确认导入选中课程",delegate{try{grid.CommitEdit(DataGridEditingUnit.Cell,true);grid.CommitEdit(DataGridEditingUnit.Row,true);var pending=new List<Course>();foreach(var row in rows.Where(r=>r.Include)){var c=row.Candidate.Value;if(c.FirstWeek==0){if(from.SelectedIndex==0||to.SelectedIndex==0)throw new Exception("请先选择缺失的教学周次。");c.FirstWeek=from.SelectedIndex;c.LastWeek=to.SelectedIndex;}if(c.FirstPeriod>0)TimetablePreferences.Apply(new Store{Timetable=state.Timetable,Courses=new List<Course>{c}});pending.Add(c);}if(pending.Count==0)throw new Exception("请选择要导入的课程。");ValidateCourses(pending);if(state.Courses.Count+pending.Count>2000)throw new Exception("课程过多。");if(Mutate(delegate{state.Courses.AddRange(pending);},"课程已导入，可Ctrl+Z撤销整批")){committed=true;if(OcrDraftPath!=null){File.Delete(OcrDraftPath);File.Delete(Path.Combine(Path.GetDirectoryName(OcrDraftPath),"ocr-draft.png"));}w.Close();}}catch(Exception ex){MessageBox.Show(w,ex.Message);}}));actions.Children.Add(Btn("保留草稿并关闭",delegate{w.Close();}));w.Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){if(!committed){grid.CommitEdit(DataGridEditingUnit.Cell,true);grid.CommitEdit(DataGridEditingUnit.Row,true);if(from.SelectedIndex>0&&to.SelectedIndex>=from.SelectedIndex)foreach(var c in candidates.Where(x=>x.Value.FirstWeek==0)){c.Value.FirstWeek=from.SelectedIndex;c.Value.LastWeek=to.SelectedIndex;}try{SaveOcrDraft(candidates,imagePath);}catch(Exception ex){e.Cancel=true;MessageBox.Show(w,"识别草稿未能保存，已保留此窗口："+ex.Message);}}};w.ShowDialog();
 }
